{"packet_id":"R002-01","doc_id":"R002","jurisdiction":"Boston, MA","category":"application_screening_fees","lifecycle":"pending_bill","title":"Proposed Boston application and screening fee cap","requirement":"A landlord would be barred from charging a prospective tenant more than $50 per application, and could charge only one such fee per applicant for a unit.","key_value":"$50 cap per application; one fee per applicant","coverage_conditions":"Prospective tenants applying for a rental unit in Boston; covers fees for credit checks, background checks and administrative processing.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Prospective tenants of rental units in Boston"},"exemptions":null,"penalty":"Fine of $300 for each violation.","effective_date":null,"citation":"Boston Docket #0842, § 2","quoted_span":"No landlord shall charge a prospective tenant an application or screening fee exceeding fifty dollars ($50) per application. A landlord may charge only one such fee per applicant for a unit.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"R002-01","doc_id":"R002","jurisdiction":"Boston, MA","category":"application_screening_fees","lifecycle":"pending_bill","title":"Proposed Boston application fee receipt and refund rule","requirement":"A landlord charging an application fee would have to give the applicant a written receipt and refund the fee within seven days if the landlord does not run the checks it was charged for.","key_value":"Refund within 7 days","coverage_conditions":"Prospective tenants in Boston who are charged an application or screening fee by a landlord.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Prospective tenants of rental units in Boston"},"exemptions":null,"penalty":"Fine of $300 for each violation.","effective_date":null,"citation":"Boston Docket #0842, § 3","quoted_span":"A landlord who charges a fee shall give the applicant a written receipt. If the landlord does not run the checks for which the fee was charged, the fee shall be refunded within seven days.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
